type": "subtopic", "title": "Language and identity", "children": [{"id": "24ec8058-cf62-45d3-b1f5-bdfef2e807b0", "type": "concept", "title": "Community membership"}, {"id": "d15ac6e0-ed00-4ba4-9058-251dc1861f98", "type": "concept", "title": "Indexicality"}, {"id": "56444005-76d7-48ba-97c9-3582694eca45", "type": "concept", "title": "Stance"}, {"id": "315c823d-7ece-48fa-9a25-aef983289fd3", "type": "concept", "title": "Ethnicity and identity"}], "description": "This subtopic connects language choices to social meaning."}, {"id": "59abc3f8-8a1b-4b78-91e9-37911b39d433", "type": "subtopic", "title": "Attitudes and discrimination", "children": [{"id": "2b3f97a0-d699-457f-9c6d-e84d8e405b3e", "type": "concept", "title": "Accent discrimination"}, {"id": "9c1c584b-e4ee-4b46-9cbe-d9242664b271", "type": "concept", "title": "Heritage speaker stigma"}, {"id": "c676b7ec-1604-4968-91c4-60e67e691728", "type": "concept", "title": "Educational gatekeeping"}, {"id": "85126980-e176-461d-8a2a-4f2296afa0a3", "type": "concept", "title": "Linguistic justice"}], "description": "Students examine linguistic prejudice and its consequences."}]}, {"id": "267e61ec-e821-4c90-9ff3-25d968124a46", "type": "topic", "title": "Bilingualism and Language Contact", "description": "This topic explores what happens when Spanish interacts with other languages in bilingual communities.", "children": [{"id": "0ad69ba1-8114-4387-b49f-d170ad38f47f", "type": "subtopic", "title": "Contact phenomena", "children": [{"id": "dd9d102d-8db4-43e2-859a-832c14ae23e1", "type": "concept", "title": "Borrowing"}, {"id": "1bf84be6-1931-430c-aba0-e25aad0744c3", "type": "concept", "title": "Calques"}, {"id": "56d7ece3-1733-464f-b539-f0c4f8acd882", "type": "concept", "title": "Convergence"}, {"id": "7d4bd995-2bd8-4c04-93ac-799112d441ec", "type": "concept", "title": "Code-switching"}], "description": "Students distinguish common outcomes of sustained language contact."}, {"id": "ef413db6-c713-42af-bb73-1948f0bb7db6", "type": "subtopic