set
  title = 'Spanish Linguistics',
  goal = 'Spanish Linguistics',
  summary = 'This course introduces students to the scientific study of Spanish as a linguistic system and as a socially situated global language. Students analyze Spanish sounds, words, sentences, meaning, history, regional varieties, bilingual contact, U.S. Spanish, and heritage-language contexts. The course combines formal analysis with authentic data. Students learn to read linguistic scholarship, use corpora and speaker data responsibly, and produce a final research-based linguistic analysis paper grounded in Spanish-language evidence.',
